        question: 'Як розрахувати точку беззбитковості для прийняття рішення про зміну ціни?',
        answer: 'Формула: Break-even (шт) = Постійні витрати / (Ціна - Змінні витрати на од.). Приклад: постійні 150к/міс, ціна 500 грн, змінні 300 грн → BEP = 150,000/(500-300) = 750 шт/міс. Якщо знижуєте ціну до 450 грн → BEP = 150,000/(450-300) = 1,000 шт (+33%). Рішення: знижувати ціну вигідно лише якщо продажі зростуть >33%.'
