        question: 'Що таке NPV і коли його використовувати?',
        answer: 'NPV (Net Present Value) - чиста приведена вартість, враховує що гроші сьогодні коштують більше ніж завтра. Використовується для оцінки довгострокових інвестицій (обладнання, нова точка, проект). Формула: NPV = -Інвестиція + CF₁/(1+r)¹ + CF₂/(1+r)² +... де r=10-15% (ставка дисконту). Якщо NPV>0 - інвестиція вигідна. Якщо NPV<0 - збиткова. Простіше: якщо термін окупності <3 років - зазвичай NPV позитивна.'
